#!/usr/bin/perl
use strict;
use warnings;
use IO::Socket;

my $host = 'localhost';
my $port = 47302;
my $name = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test';

my $sock = IO::Socket::INET->new(
    PeerAddr => $host,
    PeerPort => $port,
    Proto    => 'udp',
    Timeout  => 2
) or die "Cannot connect: $!\n";

print "Connecting to $host:$port... ";
if ($sock) {
    $sock->autoflush(1);
    $sock->send("$name\n");
    my $buf;
    $sock->recv($buf, 1024);
    print "Response: $buf\n";
    $sock->close();
} else {
    print "Failed to connect\n";
}
EOF

chmod +x check_dns4.pl && ./check_dns4.pl

