input.command:
cat > dig.go << 'EOF'
package main

import (
	"fmt"
	"net"
	"os"
	"time"

	"github.com/miekg/dns"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "Usage: dig.go <domain>")
		os.Exit(1)
	}
	domain := os.Args[1]

	c := new(dns.Client)
	c.ReadTimeout = 5 * time.Second
	c.WriteTimeout = 5 * time.Second

	msg := new(dns.Msg)
	msg.SetQuestion(dns.Fqdn(domain), dns.TypeA)

	r, _, err := c.Exchange(msg, "localhost:47302")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	for _, ans := range r.Answer {
		if t, ok := ans.(*dns.A); ok {
			fmt.Println(t.A)
		}
	}
}
EOF

